<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">   let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> p3 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> p1.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mixup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(p2);</span></span>
